package edu.lablink; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserJpaRepository users; private final PasswordEncoder passwords; private final JwtService jwt; public AuthController(UserJpaRepository users,PasswordEncoder passwords,JwtService jwt){this.users=users;this.passwords=passwords;this.jwt=jwt;} record Credentials(@NotBlank @Email String email,@NotBlank @Size(min=8,max=100) String password){} record Register(@NotBlank @Size(max=120) String name,@NotBlank @Email String email,@NotBlank @Size(min=8,max=100) String password){} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> register(@Valid @RequestBody Register body){if(users.findByEmailIgnoreCase(body.email()).isPresent())throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");return result(users.save(new UserEntity(body.name().trim(),body.email().trim().toLowerCase(),passwords.encode(body.password()),"STUDENT")));} @PostMapping("/login") Map<String,Object> login(@Valid @RequestBody Credentials body){UserEntity u=users.findByEmailIgnoreCase(body.email()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!passwords.matches(body.password(),u.getPasswordHash())||!"ACTIVE".equals(u.getStatus()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");u.login();users.save(u);return result(u);} private Map<String,Object> result(UserEntity u){return Map.of("token",jwt.issue(u),"user",Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole(),"status",u.getStatus()));}}
